mapper.select:
SELECT e.id, e.canonical_name, t.key, e.type_id, e.profile_embedding::text AS profile_embedding
FROM entities e LEFT JOIN entity_types t ON t.id = e.type_id
WHERE e.kb_id = #{kbId} AND e.merged_into IS NULL
  AND e.id <> #{newId}
  AND lower(e.canonical_name) <> #{lower}
  AND (
    (char_length(e.canonical_name) >= #{minChars}
     AND (lower(e.canonical_name) LIKE '%' || #{lower} || '%'
          OR #{lower} LIKE '%' || lower(e.canonical_name) || '%'))
    OR EXISTS (
      SELECT 1 FROM facts nf
        JOIN relation_types nr ON nr.id = nf.predicate_id
       WHERE nf.subject_id = e.id AND nf.kb_id = #{kbId}
         AND nr.builtin AND nr.key = 'known_as'
         AND nf.invalidated_at IS NULL
         AND char_length(nf.object_value->>'value') >= #{minChars}
         AND (lower(nf.object_value->>'value') LIKE '%' || #{lower} || '%'
              OR #{lower} LIKE '%' || lower(nf.object_value->>'value') || '%')))
ORDER BY char_length(e.canonical_name)
LIMIT #{limit}

WITH RECURSIVE up(id) AS (
     SELECT #{typeId}::uuid
     UNION
     SELECT p.parent_id FROM entity_type_parents p JOIN up ON p.child_id = up.id
 ), hit(id) AS (
     SELECT d.b_id FROM entity_type_disjoint d JOIN up ON d.a_id = up.id
      WHERE d.kb_id = #{kbId}
 ), down(id) AS (
     SELECT id FROM hit
     UNION
     SELECT p.child_id FROM entity_type_parents p JOIN down ON p.parent_id = down.id
 )
 SELECT id FROM down

mapper.update:
UPDATE entities
 SET type_id = #{typeId}, type_source = 'extracted', updated_at = now()
 WHERE id = #{id}

UPDATE resolution_reviews
 SET status = 'merged', decided_at = now(), decided_by = #{userId}, rationale = #{rationale}
 WHERE id = #{reviewId}

UPDATE resolution_reviews
 SET status = 'kept', decided_at = now(), decided_by = #{userId}, rationale = #{rationale}
 WHERE id = #{reviewId}

mapper.select:
WITH RECURSIVE d(id) AS (
     SELECT #{root}::uuid
     UNION
     SELECT p.child_id FROM entity_type_parents p JOIN d ON d.id = p.parent_id
 )
 SELECT d.id FROM d JOIN entity_types t ON t.id = d.id WHERE t.kb_id = #{kbId}
